    [Fact]
    public void Absolute_layout_column_reverse_margin_border() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(200.0f));
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(200.0f));
        tree.SetFlexDirection(root, FlexDirection.ColumnReverse);

        var rootChild0 = tree.CreateNode();
        tree.SetPositionType(rootChild0, PositionType.Absolute);
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Points(50.0f));
        tree.SetDimension(rootChild0, Dimension.Height, StyleLength.Points(50.0f));
        tree.SetPosition(rootChild0, Edge.Left, StyleLength.Points(5.0f));
        tree.SetPosition(rootChild0, Edge.Right, StyleLength.Points(3.0f));
        tree.SetMargin(rootChild0, Edge.Right, StyleLength.Points(4.0f));
        tree.SetMargin(rootChild0, Edge.Left, StyleLength.Points(3.0f));
        tree.SetBorder(rootChild0, Edge.Right, StyleLength.Points(7.0f));
        tree.SetBorder(rootChild0, Edge.Left, StyleLength.Points(1.0f));
        tree.InsertChild(root, rootChild0, 0);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(200.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(8.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(150.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild0), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(200.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(200.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(143.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(150.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild0), Tolerance);
    }
